import java.util.*;

public class Main {
    static final long MOD = 1000000007L;
    static final int LIM = 1 << 20;

    static class Solver {
        int n, m;
        long[] cnt = new long[LIM];
        long[] cnt2 = new long[LIM];
        long[][] a;
        int[] rev = new int[LIM];
        int[] rev2 = new int[LIM];

        long modpow(long x, long p) {
            long r = 1;
            while (p > 0) {
                if ((p & 1) == 1) r = r * x % MOD;
                x = x * x % MOD;
                p >>= 1;
            }
            return r;
        }

        // next permutation in lexicographic order, returns false if no more
        boolean nextPermutation(int[] arr) {
            int i = arr.length - 2;
            while (i >= 0 && arr[i] >= arr[i + 1]) i--;
            if (i < 0) return false;
            int j = arr.length - 1;
            while (arr[j] <= arr[i]) j--;
            swap(arr, i, j);
            reverse(arr, i + 1, arr.length - 1);
            return true;
        }

        void swap(int[] arr, int i, int j) {
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }

        void reverse(int[] arr, int l, int r) {
            while (l < r) {
                swap(arr, l, r);
                l++;
                r--;
            }
        }

        void dfs1(int cur, ArrayList<Integer> con, long prob) {
            if (cur == m) {
                int nxt = 0, id = 0;
                for (int j = 0; j < (1 << n); ++j) {
                    if (Integer.bitCount(j) != m) continue;
                    ArrayList<Integer> vi = new ArrayList<>();
                    for (int i = 0; i < n; ++i) if ((j >> i & 1) == 1) vi.add(i);
                    int[] arr = new int[vi.size()];
                    for (int k = 0; k < arr.length; k++) arr[k] = vi.get(k);
                    Arrays.sort(arr);
                    boolean ok = false;
                    do {
                        boolean good = true;
                        for (int x = 0; x < m; ++x) {
                            if (((con.get(x) >> arr[x]) & 1) == 0) {
                                good = false;
                                break;
                            }
                        }
                        if (good) {
                            ok = true;
                            break;
                        }
                    } while (nextPermutation(arr));
                    if (ok) id |= (1 << nxt);
                    ++nxt;
                }
                cnt[id] += prob;
                return;
            }
            for (int j = 0; j < (1 << n); ++j) {
                con.add(j);
                long nw = prob;
                for (int k = 0; k < n; ++k) {
                    if ((j >> k & 1) == 1) nw = nw * a[cur][k] % MOD;
                    else nw = nw * (MOD + 1 - a[cur][k]) % MOD;
                }
                dfs1(cur + 1, con, nw);
                con.remove(con.size() - 1);
            }
        }

        void dfs2(int cur, ArrayList<Integer> con, long prob) {
            if (cur == n) {
                int nxt = 0, id = 0;
                for (int j = 0; j < (1 << n); ++j) {
                    if (Integer.bitCount(j) != n - m) continue;
                    ArrayList<Integer> vi = new ArrayList<>();
                    for (int i = 0; i < n; ++i) if ((j >> i & 1) == 1) vi.add(i);
                    int[] arr = new int[vi.size()];
                    for (int k = 0; k < arr.length; k++) arr[k] = vi.get(k);
                    Arrays.sort(arr);
                    boolean ok = false;
                    do {
                        boolean good = true;
                        for (int x = 0; x < n - m; ++x) {
                            if (((con.get(x) >> arr[x]) & 1) == 0) {
                                good = false;
                                break;
                            }
                        }
                        if (good) {
                            ok = true;
                            break;
                        }
                    } while (nextPermutation(arr));
                    if (ok) id |= (1 << nxt);
                    ++nxt;
                }
                cnt2[id] += prob;
                return;
            }
            for (int j = 0; j < (1 << n); ++j) {
                con.add(j);
                long nw = prob;
                for (int k = 0; k < n; ++k) {
                    if ((j >> k & 1) == 1) nw = nw * a[cur][k] % MOD;
                    else nw = nw * (MOD + 1 - a[cur][k]) % MOD;
                }
                dfs2(cur + 1, con, nw);
                con.remove(con.size() - 1);
            }
        }

        void solve() {
            Scanner sc = new Scanner(System.in);
            n = sc.nextInt();
            a = new long[n][n];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    long val = sc.nextLong();
                    a[i][j] = val * modpow(100L, MOD - 2) % MOD;
                    a[i][j] = (a[i][j] % MOD + MOD) % MOD;
                }
            }
            if (n == 1) {
                System.out.println(a[0][0]);
                return;
            }
            m = n / 2;

            dfs1(0, new ArrayList<>(), 1);
            for (int i = 0; i < LIM; ++i) cnt[i] %= MOD;
            for (int i = 0; i < 20; ++i) {
                for (int j = 0; j < LIM; ++j) {
                    if ((j >> i & 1) == 1) {
                        cnt[j] += cnt[j ^ (1 << i)];
                        cnt[j] %= MOD;
                    }
                }
            }
            long all = cnt[LIM - 1];

            dfs2(m, new ArrayList<>(), 1);
            for (int i = 0; i < LIM; ++i) cnt2[i] %= MOD;

            Arrays.fill(rev, -1);
            int nd = 0;
            for (int i = 0; i < (1 << n); ++i) {
                if (Integer.bitCount(i) == m) rev[i] = nd++;
            }

            Arrays.fill(rev2, -1);
            nd = 0;
            // cor array size: number of subsets of size n-m, which is at most LIM
            int[] cor = new int[LIM];
            for (int i = 0; i < (1 << n); ++i) {
                if (Integer.bitCount(i) == n - m) {
                    cor[nd] = rev[(1 << n) - 1 - i];
                    rev2[i] = nd++;
                }
            }

            long ans = 0;
            for (int i = 0; i < (1 << nd); ++i) {
                long cur = cnt2[i];
                int mask = 0;
                for (int j = 0; j < nd; ++j) {
                    if (((i >> j) & 1) == 0) {
                        mask += (1 << cor[j]);
                    }
                }
                ans += cur * (all - cnt[mask]) % MOD;
            }
            System.out.println((ans % MOD + MOD) % MOD);
        }
    }

    public static void main(String[] args) {
        Solver solver = new Solver();
        solver.solve();
    }
}
